from typing import Any
from typing import BinaryIO
from typing import TextIO
import csv
import io
REQUIRED_COLUMNS = ('name', 'email')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


# pcat: importers.users_csv.parse@v1
def import_users(source: str | TextIO, max_rows: int=MAX_ROWS) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    reader = csv.DictReader(io.StringIO(source) if isinstance(source, str) else source)
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return ([], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}])
    reader.fieldnames = header
    valid, errors, seen = ([], [], set())
    for count, row in enumerate(reader, 1):
        if count > max_rows:
            stop = f'more than {max_rows} rows; stopped'
            errors.append({'row': reader.line_num, 'errors': [stop]})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        age_raw = (row.get('age') or '').strip()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)


def xlsx_to_csv_text(data: BinaryIO, max_rows: int = MAX_ROWS) -> str:
    """Convert the first sheet of an .xlsx file to CSV text, keeping row numbers
    aligned with the spreadsheet (one CSV line per sheet row)."""
    from openpyxl import load_workbook

    workbook = load_workbook(data, read_only=True, data_only=True)
    try:
        sheet = workbook.active
        out = io.StringIO()
        writer = csv.writer(out, lineterminator='\n')
        for index, cells in enumerate(sheet.iter_rows(values_only=True), 1):
            if index > max_rows + 2:  # header + cap + one extra to trigger the cap error
                break
            values = []
            for cell in cells:
                if cell is None:
                    values.append('')
                elif isinstance(cell, float) and cell.is_integer():
                    values.append(str(int(cell)))  # Excel stores whole numbers as floats
                else:
                    text = str(cell)
                    values.append(' '.join(text.splitlines()))  # keep one line per row
            writer.writerow(values)
        return out.getvalue()
    finally:
        workbook.close()


def validate_user_upload(filename: str, data: bytes, max_rows: int = MAX_ROWS) -> dict[str, Any]:
    """Validate an uploaded users export (.xlsx or .csv).

    Returns {"valid_users": [...], "invalid_rows": [{"row", "errors"}], "total_valid",
    "total_invalid"}. Every row is checked; validation never stops at the first error.
    Row numbers match the spreadsheet row (header is row 1).
    """
    name = (filename or '').lower()
    try:
        if name.endswith('.xlsx'):
            text = xlsx_to_csv_text(io.BytesIO(data), max_rows)
        elif name.endswith('.csv'):
            text = data.decode('utf-8-sig')
        else:
            return _upload_failure('unsupported file type; upload .xlsx or .csv')
    except UnicodeDecodeError:
        return _upload_failure('file is not valid UTF-8 text')
    except Exception:
        return _upload_failure('file could not be read as a valid spreadsheet')

    valid_users, errors = import_users(text, max_rows)
    errors = sorted(errors, key=lambda e: e['row'])
    return {
        'valid_users': valid_users,
        'invalid_rows': errors,
        'total_valid': len(valid_users),
        'total_invalid': len(errors),
    }


def _upload_failure(message: str) -> dict[str, Any]:
    return {
        'valid_users': [],
        'invalid_rows': [{'row': 1, 'errors': [message]}],
        'total_valid': 0,
        'total_invalid': 1,
    }

